H('410.d.2.C',4,"Galileo studied the strength of beams and noted that scaling a structure up in size makes it relatively:","weaker",["stronger","cheaper","brighter"],"Weight grows faster than strength.")
H('410.d.2.D',3,"A structural engineer who designs buildings to resist loads uses the field of:","statics",["linguistics","astronomy","geology only"],"Statics analyzes forces in equilibrium.")
H('410.d.2.D',4,"Careers that use statics include civil engineer, architect, and:","mechanical designer",["pastry chef","poet","DJ"],"Many design careers rely on statics.")
H('410.d.3.A',3,"A beam measured as 96 inches long is how many feet long?","8 feet",["12 feet","9 feet","80 feet"],"96 / 12 = 8.")
H('410.d.3.A',4,"Which tool would best measure a beam's length to the nearest 1/16 inch?","tape measure with 1/16 inch marks",["bathroom scale","clock","thermometer"],"Choose a tool with suitable resolution.")
H('410.d.3.B',3,"The prefix 'kilo' means:","one thousand times",["one hundredth of","one million times","one tenth of"],"1 kilo = 1,000.")
H('410.d.3.B',4,"Convert 3.5 kilonewtons to newtons.","3,500 N",["350 N","35 N","35,000 N"],"3.5 x 1,000 = 3,500.")
H('410.d.3.C',3,"An apple weighs approximately:","1 newton",["1 kilonewton","100 newtons","1 meganewton"],"A 100 g apple weighs about 1 N.")
H('410.d.3.C',4,"A force of about 1 pound is closest to:","4.45 newtons",["45 newtons","0.45 newtons","450 newtons"],"1 lb is about 4.45 N.")
H('410.d.4.A',3,"A book presses down on a table with 10 N. By Newton's third law, the table pushes up on the book with:","an equal 10 N force",["a 5 N force","a 20 N force","no force"],"Action and reaction are equal.")
H('410.d.4.A',4,"In a static system, every action force has a reaction force that is:","equal in size and opposite in direction",["larger and in the same direction","smaller","absent"],"That is Newton's third law.")
H('410.d.4.B',3,"Gears are used to transmit motion and change:","speed and torque",["color and size","price only","sound only"],"Gear ratios trade speed for torque.")
H('410.d.4.B',4,"A pulley is used mainly to change the direction of a:","force applied by a rope",["gear tooth","bolt","magnet"],"Pulleys redirect cable force.")
H('410.d.4.C',3,"A gear with 40 teeth drives a gear with 10 teeth. The smaller gear turns:","faster than the larger",["slower than the larger","at the same speed","not at all"],"Fewer teeth means faster rotation.")
H('410.d.4.C',4,"A lever with the pivot closer to the load than to the effort gives a mechanical advantage that is:","greater than 1",["less than 1","exactly 0","negative"],"A longer effort arm multiplies force.")
H('410.d.4.D',3,"A uniform distributed load of 50 N/m acts over 6 m. The equivalent point load is:","300 N",["56 N","8.3 N","3,000 N"],"50 x 6 = 300.")
H('410.d.4.D',4,"The equivalent point load of a uniform distributed load acts at the:","midpoint of the loaded length",["end of the beam","support","edge of the paper"],"The resultant acts at the centroid.")
H('410.d.4.E',3,"A line load is measured in newtons per:","meter",["second","kilogram","volt"],"Line loads are force per length.")
H('410.d.4.E',4,"Pressure on a roof from snow is measured as force per:","unit area",["unit length","unit time","unit mass"],"Area loads are force per area.")
H('410.d.4.F',3,"Torque is commonly measured in:","newton-meters",["newtons per meter","watts","kilograms"],"Torque = force x distance.")
H('410.d.4.F',4,"A 20 N force applied 0.5 m from a pivot, perpendicular to the lever, produces a torque of:","10 N-m",["40 N-m","20.5 N-m","0.025 N-m"],"20 x 0.5 = 10.")
H('410.d.4.G',3,"Efficiency of a machine is the ratio of useful output work to:","input work",["output sound","machine weight","machine price"],"Efficiency = output / input.")
H('410.d.4.G',4,"A machine takes in 500 J and delivers 400 J of useful work. Its efficiency is:","80 percent",["125 percent","20 percent","400 percent"],"400 / 500 = 0.8.")
H('410.d.4.H',3,"A couple consists of two forces that are equal, opposite, and:","parallel but not along the same line",["along the same line","perpendicular","zero"],"Offset parallel forces create rotation.")
H('410.d.4.H',4,"A couple produces:","pure rotation with no net force",["net translation","no effect","a random force"],"The forces cancel but the moment remains.")
H('410.d.5.A',3,"Which of these is a vector quantity?","velocity",["mass","temperature","time"],"Velocity has direction.")
H('410.d.5.A',4,"A scalar quantity has magnitude only, while a vector has magnitude and:","direction",["color","weight tag","price"],"Vectors have direction.")
H('410.d.5.B',3,"A force vector is drawn as an arrow. The arrow's length represents the vector's:","magnitude",["direction","color","name"],"Length is scaled to size.")
H('410.d.5.B',4,"The way the arrowhead points on a force arrow shows the force's:","direction",["magnitude","mass","price"],"The arrowhead shows which way it acts.")
H('410.d.5.C',3,"A force of 5 units to the right and 12 units up can be written in component notation as:","(5, 12)",["(12, 5)","(5, -12)","(-5, 12)"],"Write horizontal then vertical.")
H('410.d.5.C',4,"The magnitude of the force (5, 12) is:","13",["17","7","60"],"sqrt(25 + 144) = 13.")
H('410.d.5.D',3,"A 100 N force acts at 30 degrees above the horizontal. Its horizontal component is 100 cos 30, which is about:","86.6 N",["50 N","100 N","173 N"],"cos 30 = 0.866.")
H('410.d.5.D',4,"For the same 100 N force at 30 degrees above horizontal, the vertical component is about:","50 N",["86.6 N","30 N","130 N"],"100 sin 30 = 50.")
H('410.d.5.E',3,"Adding two vectors by placing the tail of the second at the tip of the first is called the:","tip-to-tail method",["tail-to-tail division","random method","subtraction"],"Tip-to-tail finds the resultant graphically.")
H('410.d.5.E',4,"Two perpendicular forces of 3 N and 4 N have a resultant of:","5 N",["7 N","1 N","12 N"],"sqrt(9 + 16) = 5.")
H('410.d.5.F',3,"The principle of transmissibility says a force can be moved along its:","line of action",["color","label","unit"],"The external effect on a rigid body is unchanged.")
H('410.d.5.F',4,"A free-body diagram shows an isolated object and all the:","forces acting on it",["colors on it","words about it","prices of it"],"FBDs include all external forces.")
H('410.d.5.G',3,"The moment of a force about a point equals the force times the:","perpendicular distance",["parallel distance","mass","speed"],"M = F x d, with d perpendicular.")
H('410.d.5.G',4,"A 40 N force acts perpendicular to a wrench 0.25 m from the bolt. The moment about the bolt is:","10 N-m",["160 N-m","40.25 N-m","0.00625 N-m"],"40 x 0.25 = 10.")
H('410.d.5.H',3,"Varignon's theorem says the moment of a force about a point equals the sum of the moments of its:","components",["colors","units","labels"],"Component moments add to the total.")
H('410.d.5.H',4,"Using components can simplify finding a moment because each component's perpendicular distance is often:","easier to determine",["impossible to find","always zero","unrelated"],"Components align with axes.")
H('410.d.5.I',3,"A force can be moved to a different point on a body if a corresponding moment is added. This creates a:","force-couple system",["color scheme","price list","unit set"],"Equivalent systems simplify analysis.")
H('410.d.5.I',4,"Replacing several loads on a beam with one equivalent force and one couple makes the beam easier to:","analyze",["paint","sell","name"],"Equivalent loads simplify calculations.")
H('410.d.6.A',3,"The centroid of an object is its geometric center, while the center of mass is the point where its:","mass is balanced",["color changes","surface ends","price is set"],"Center of mass accounts for how mass is distributed.")
H('410.d.6.A',4,"For an object of uniform density, the centroid and the center of mass are:","at the same location",["always far apart","outside the object","undefined"],"Uniform density makes them coincide.")
H('410.d.6.B',3,"The centroid of a rectangle that is 8 cm wide and 6 cm tall, measured from its lower left corner, is at:","(4 cm, 3 cm)",["(8 cm, 6 cm)","(3 cm, 4 cm)","(0 cm, 0 cm)"],"Half the width and half the height.")
H('410.d.6.B',4,"To find the centroid of a complex shape, an engineer often splits it into simple shapes and uses a:","weighted average of their centroids",["random guess","color chart","price list"],"Area-weighted averaging locates the combined centroid.")
H('410.d.6.C',3,"The balance point of a uniform solid sphere is found at its:","center",["surface","top","bottom"],"A symmetric uniform body balances at its center.")
H('410.d.6.C',4,"A flat uniform plate is hung from one corner and then another. The center of mass lies where the plumb lines:","cross",["end","start","stay parallel"],"The intersection marks the balance point.")
H('410.d.7.A',3,"A lever rotates about a fixed point called the:","pivot",["gear","chain","bolt head"],"A pivot is the point of rotation.")
H('410.d.7.A',4,"A 30 N child sits 2 m from the pivot of a seesaw. A second child on the other side balances it at 1 m. The second child weighs:","60 N",["15 N","30 N","90 N"],"30 x 2 = W x 1, so W = 60.")
H('410.d.7.B',3,"A ladder leaning on a wall with only friction at the floor stays put when friction is:","large enough to balance the horizontal push",["zero","less than the push","not present"],"Static friction must supply the balancing force.")
H('410.d.7.B',4,"A smoother floor lowers friction, making a leaning ladder more likely to:","slip",["grow","stick harder","float"],"Less friction allows sliding.")
H('410.d.7.C',3,"A person standing on the ladder adds a downward force. To stay stable, the floor friction must now be:","greater",["smaller","absent","unchanged in all cases"],"More load requires more friction to hold.")
H('410.d.7.C',4,"A crate is pushed with a force less than the maximum static friction. The crate:","stays at rest",["accelerates","tips up instantly","speeds up"],"The friction force matches the push until its limit.")
H('410.d.7.D',3,"The maximum static friction force equals the coefficient of static friction times the:","normal force",["speed","volume","color"],"f = mu x N.")
H('410.d.7.D',4,"A 100 N block sits on a surface with a static friction coefficient of 0.4. The maximum static friction is:","40 N",["250 N","0.4 N","140 N"],"0.4 x 100 = 40.")
H('410.d.8.A',3,"A support that allows rotation but prevents movement in both horizontal and vertical directions is called a:","pin support",["roller support","free end","spring"],"A pin gives two reaction forces.")
H('410.d.8.A',4,"A support that resists horizontal and vertical force and also rotation is a:","fixed support",["roller support","pin support","free end"],"A fixed support provides two forces and a moment.")
H('410.d.8.B',3,"A roller support provides how many reaction forces?","one",["two","three","none"],"It resists force only perpendicular to its surface.")
H('410.d.8.B',4,"A planar fixed support restricts how many degrees of freedom?","three",["one","two","zero"],"Two translations and one rotation.")
H('410.d.8.C',3,"A bridge is built with a pin at one end and a roller at the other so that the bridge can:","expand and contract with temperature",["float","spin","vanish"],"The roller allows thermal movement.")
H('410.d.8.C',4,"Replacing a roller with a pin on a long bridge could cause large stresses when it heats because the bridge:","cannot lengthen freely",["gets lighter","turns invisible","loses color"],"Restrained expansion creates force.")
H('410.d.8.D',3,"A fixed support at the wall end of a cantilever beam provides a reaction moment to resist the beam's tendency to:","rotate",["shrink","melt","float"],"The moment prevents rotation.")
H('410.d.8.D',4,"A beam on a pin and a roller has how many unknown reaction components in a plane?","three",["one","two","six"],"Two from the pin and one from the roller.")
H('410.d.9.A',3,"A complete free-body diagram includes the object and all the:","external forces and moments on it",["internal colors","nearby words","unrelated objects"],"FBDs show all outside influences.")
H('410.d.9.A',4,"When drawing a free-body diagram, a support is replaced by its:","reaction forces",["name","price","paint"],"Supports are shown as reactions.")
H('410.d.9.B',3,"An object in static equilibrium has a net force of:","zero",["one newton","ten newtons","infinity"],"Equilibrium means no net force or moment.")
H('410.d.9.B',4,"Besides zero net force, static equilibrium requires zero net:","moment",["color","price","volume"],"Both translation and rotation must be balanced.")
H('410.d.9.C',3,"In two dimensions, the translational equilibrium equations are the sum of forces in x equal to zero and the sum of forces in:","y equal to zero",["x equal to ten","z equal to ten","time equal to zero"],"Two force equations in a plane.")
H('410.d.9.C',4,"The rotational equilibrium equation in a plane states that the sum of moments about any point is:","zero",["one","negative","the weight"],"Moments balance in equilibrium.")
H('410.d.9.D',3,"A beam is supported at both ends and carries a 100 N load at its center. Each support carries:","50 N",["100 N","25 N","200 N"],"By symmetry, 100 / 2 = 50.")
H('410.d.9.D',4,"A 10 m beam on supports at its ends carries a 300 N load 2 m from the left end. The right support reaction is:","60 N",["240 N","30 N","150 N"],"Moments about left: R x 10 = 300 x 2, so R = 60.")
H('410.d.10.A',3,"In a truss, each member is generally loaded only in:","tension or compression",["bending only","twisting only","sound only"],"Two-force members carry axial loads.")
H('410.d.10.A',4,"A plane truss made of triangles is stable because a triangle cannot change its shape without changing the:","length of a side",["color","price","name"],"Triangles are rigid.")
H('410.d.10.B',3,"The method of joints solves for member forces by applying equilibrium to each:","connection point",["paint layer","label","weld color"],"Joint equilibrium gives member forces.")
H('410.d.10.B',4,"The method of sections finds member forces by cutting the truss and applying equilibrium to:","one side of the cut",["the whole planet","no part","the paint"],"A section isolates the cut members.")
H('410.d.10.C',3,"A truss member that is being pulled apart is in:","tension",["compression","torsion","shear only"],"Pulling means tension.")
H('410.d.10.C',4,"A truss member that is being pushed together is in:","compression",["tension","stretch only","neutral flow"],"Pushing means compression.")
H('410.d.10.D',3,"A cable or rope can carry only:","tension",["compression","bending","twisting"],"Flexible members cannot resist pushing.")
H('410.d.10.D',4,"A slender bar in compression can fail by sideways bending called:","buckling",["melting","tension","polishing"],"Buckling limits compression members.")
H('410.d.10.E',3,"A zero-force member in a truss is one that carries:","no load under the given loading",["maximum load","all the weight","extra paint"],"Some members carry no force in certain loadings.")
H('410.d.10.E',4,"Members in a loaded truss may be in tension or compression depending on the:","direction of the loads",["name of the engineer","color of the truss","time of day"],"Load direction determines the member state.")
H('410.d.10.F',3,"A tensegrity structure is held in shape by a balance of continuous tension and isolated:","compression members",["magnets","bubbles","shadows"],"Struts float within a tension network.")
H('410.d.10.F',4,"Bridge trusses often use triangles because triangles make the structure:","rigid with efficient use of material",["floppy","colorful","heavy only"],"Triangles resist shape change.")
H('410.d.11.A',3,"A two-dimensional structure analysis assumes all forces and members lie in one:","plane",["season","room","color"],"2D means flat analysis.")
H('410.d.11.A',4,"A three-dimensional analysis needs equilibrium equations in x, y, and:","z",["w","t only","q"],"3D adds the third axis.")
H('410.d.11.B',3,"Adding a third dimension to a structure generally increases the number of:","equations and unknowns",["colors","labels only","words"],"Six equilibrium equations replace three.")
H('410.d.11.B',4,"In three dimensions, the number of equilibrium equations for a rigid body is:","six",["two","three","nine"],"Three force and three moment equations.")
H('410.d.11.C',3,"A flat frame that is stable in its own plane can still fall over sideways if it has no:","out-of-plane bracing",["paint","label","name"],"Sideways bracing supplies 3D stability.")
H('410.d.11.C',4,"A tall sign supported by one planar truss can be unstable against wind from the side unless a second plane of members is:","added",["removed","painted","hidden"],"Bracing in the second plane gives stability.")
H('411.d.1',3,"An engineering team finds that a cheaper part may fail early. The professional choice is to:","report the risk and fix the design",["hide the risk","ship it quickly","blame the customer"],"Safety and honesty come before cost savings.")
H('411.d.1',4,"Safe lab practice when using power tools includes wearing:","eye protection",["loose sleeves","open sandals","earbuds only"],"Protective gear prevents injuries.")
H('411.d.2.A',3,"The first stage of the engineering design process is to define the:","problem",["price","color","logo"],"Design starts with a clear problem statement.")
H('411.d.2.A',4,"A good problem statement describes the need, the users, and the:","constraints",["weather forecast","team mascot","paint brand"],"Constraints bound the solution.")
H('411.d.2.B',3,"Gathering information about similar products and user needs is called:","research",["guessing","painting","shipping"],"Research informs the design.")
H('411.d.2.B',4,"Which source would help a team learn how customers use a product?","a user survey",["a random coin flip","a color wheel","a clock"],"Surveys collect user needs.")
H('411.d.2.C',3,"Brainstorming many possible solutions without judging them is called:","ideation",["inspection","shipping","accounting"],"Ideation generates options.")
H('411.d.2.C',4,"During ideation, the team should aim for a large number of:","different ideas",["identical ideas","criticisms","deadlines"],"Quantity and variety spark good concepts.")
H('411.d.2.D',3,"A tool that scores design options against weighted criteria is a:","decision matrix",["tape measure","paint chart","rubber band"],"A matrix compares concepts objectively.")
H('411.d.2.D',4,"In a decision matrix, the option with the highest weighted total is usually:","selected for development",["discarded","hidden","painted"],"The best-scoring concept moves forward.")
H('411.d.2.E',3,"A scale drawing that shows the exact shape and size of a part is a:","technical drawing",["cartoon","poster","diary"],"Technical drawings communicate dimensions.")
H('411.d.2.E',4,"A quick physical model made of cardboard to test a concept is a:","prototype",["final product","logo","invoice"],"Prototypes test ideas cheaply.")
H('411.d.2.F',3,"A fair test changes only one variable at a time so the team can tell what caused the:","result",["weather","lunch","music"],"Single-variable tests isolate cause.")
H('411.d.2.F',4,"Testing the prototype under realistic load is part of:","experimental design and testing",["packaging","advertising","payroll"],"Tests show whether the design performs.")
H('411.d.2.G',3,"Repeating design steps to improve a solution based on test results is called:","iteration",["subtraction","retirement","storage"],"Iteration refines the design.")
H('411.d.2.G',4,"After a prototype fails a test, the team should:","analyze why and revise the design",["stop forever","hide the data","blame the tester"],"Failures guide improvements.")
H('411.d.2.H',3,"Sharing the final design with others through reports and presentations is the step of:","communication",["demolition","deletion","hiding"],"The team documents and presents results.")
H('411.d.2.H',4,"A design presentation should include the problem, the solution, and the:","test evidence",["lunch menu","team playlist","paint sample"],"Evidence supports the solution.")
H('411.d.3.A',3,"A team has 10 days to build a model. A good time management step is to make a:","schedule with due dates",["longer lunch","random plan","nap plan"],"Schedules keep work on track.")
H('411.d.3.A',4,"Doing the hardest or longest tasks first helps a team avoid:","last-minute delays",["early starts","good grades","planning"],"Early progress reduces risk.")
H('411.d.3.B',3,"A limit on money, time, or materials in a project is a:","constraint",["feature","bonus","color"],"Constraints restrict choices.")
H('411.d.3.B',4,"A project has a fixed budget of 50 dollars. That budget is a:","cost constraint",["time constraint","size goal","color preference"],"Budget limits spending.")
H('411.d.3.C',3,"A milestone in a project is a:","key checkpoint",["lunch break","mistake","logo"],"Milestones mark progress points.")
H('411.d.3.C',4,"A deliverable is a:","product or document the team must hand in",["rumor","lunch order","spare part"],"Deliverables are required outputs.")
H('411.d.3.D',3,"Which is a written form of communication on a team?","an email or report",["a hand wave","a nod","a whistle"],"Written communication leaves a record.")
H('411.d.3.D',4,"A team uses a shared document so everyone sees the same:","current information",["old drafts only","private notes only","blank pages"],"Shared documents keep teams aligned.")
H('411.d.3.E',3,"When a team is stuck, a useful problem-solving strategy is to break the problem into:","smaller parts",["bigger problems","bad ideas","fewer facts"],"Decomposition makes problems manageable.")
H('411.d.3.E',4,"Working backward from the goal to the first step is a strategy called:","backward planning",["random guessing","skipping","stalling"],"Backward planning clarifies steps.")
H('411.d.4.A',3,"Helpful critique of a teammate's idea should focus on the:","work, not the person",["person, not the work","teammate's looks","noise"],"Constructive critique targets the idea.")
H('411.d.4.A',4,"A respectful critique includes a specific suggestion for:","how to improve",["why the person is bad","who to blame","what to hide"],"Specific advice helps.")
H('411.d.4.B',3,"A teammate who listens, shares tasks fairly, and meets deadlines shows good:","teamwork skills",["solo habits","sleep habits","spelling"],"Reliable cooperation helps teams.")
H('411.d.4.B',4,"If two teammates disagree, a good first step is to:","listen to each side",["ignore both","shout","quit"],"Understanding both views leads to solutions.")
H('411.d.4.C',3,"A bar chart that shows tasks over time with start and end dates is a:","Gantt chart",["pie chart","line graph of weather","map"],"Gantt charts schedule tasks.")
H('411.d.4.C',4,"A work breakdown structure divides a project into smaller:","tasks",["colors","rooms","voices"],"It lists the work in pieces.")
H('411.d.4.D',3,"A team member contributes positively by completing assigned tasks:","on time and with quality",["late","partly","never"],"Reliable work supports the team.")
H('411.d.4.D',4,"Offering to help a teammate who is behind shows:","positive group contribution",["poor planning","cheating","bad manners"],"Helping improves team results.")
H('411.d.5.A',3,"A short summary at the start of a report that gives the main findings is an:","executive summary",["appendix","footnote","index card"],"It gives busy readers the key points.")
H('411.d.5.A',4,"A reverse engineering report documents how an existing product is:","built and how it works",["sold","advertised","named"],"It records the analysis of a product.")
H('411.d.5.B',3,"Technical reports usually include headings so readers can find:","sections quickly",["only colors","only pictures","nothing"],"Format aids navigation.")
H('411.d.5.B',4,"A report uses figures and captions to help explain:","data and designs",["jokes","lunch","weather"],"Visuals support understanding.")
H('411.d.5.C',3,"A well-organized report presents the introduction, then the body, then the:","conclusion",["title again","lunch","blank page"],"Logical order helps the reader.")
H('411.d.5.C',4,"Steps in a procedure should be listed in the:","order they are done",["order of difficulty","random order","alphabetical order"],"Sequence must match the real process.")
H('411.d.6.A',3,"Mechanical design is used to make products such as cars, bicycles, and:","washing machines",["poems","songs","clouds"],"Many machines are mechanically designed.")
H('411.d.6.A',4,"A company that makes engines and gearboxes is in the field of:","mechanical design and manufacturing",["music publishing","fashion only","poetry"],"These parts require mechanical engineering.")
H('411.d.6.B',3,"A commercial use of mechanical design is the production of:","elevators",["lullabies","stories","dreams"],"Elevators use mechanisms and structures.")
H('411.d.6.B',4,"Wind turbines, cranes, and pumps are examples of products with:","mechanical design",["only graphic design","no moving parts","no materials"],"Each has designed mechanisms.")
H('411.d.6.C',3,"A household item with a designed mechanism is a:","can opener",["pillow","blanket","rug"],"Can openers use gears and levers.")
H('411.d.6.C',4,"A door lock uses a mechanism to convert a key turn into:","bolt movement",["light","sound only","heat"],"The lock moves the bolt.")
H('411.d.7.A',3,"A computer model that shows how parts of a machine move together is a:","virtual model of a mechanism",["paper plane","poster","receipt"],"Virtual models simulate motion.")
H('411.d.7.A',4,"An advantage of testing a mechanism in a virtual model first is that the team can find problems:","before building it",["after selling it","never","by luck"],"Simulation saves time and material.")
H('411.d.7.B',3,"The motion that drives a mechanism, such as a turning crank, is the:","input",["output","waste","label"],"The input starts the motion.")
H('411.d.7.B',4,"The motion that comes out of a mechanism, such as a slider moving, is the:","output",["input","error","constraint"],"The output is the resulting motion.")
H('411.d.7.C',3,"A mechanism that transmits rotation between toothed wheels is a:","gear train",["belt","screw jack","spring"],"Gears mesh to pass rotation.")
H('411.d.7.C',4,"A mechanism that turns rotation into straight-line motion along a threaded rod is a:","lead screw",["gear pair","pulley belt","cam"],"Screw threads convert rotation to linear motion.")
H('411.d.7.D',3,"Changing a gear's number of teeth in a model changes the mechanism's:","speed ratio",["color","label","price tag"],"Tooth count sets the ratio.")
H('411.d.7.D',4,"Making a lever arm longer in the model changes the force and the:","distance moved",["font","paint","brand"],"Lever geometry trades force for distance.")
H('411.d.8.A',3,"Before taking a product apart for reverse engineering, you should gather the correct:","tools",["paints","toys","songs"],"The right tools prevent damage.")
H('411.d.8.A',4,"While disassembling a product, a good habit is to photograph and label each:","removed part",["window","table leg","cloud"],"Documentation helps reassembly.")
H('411.d.8.B',3,"Keeping notes, sketches, and photos while taking something apart is called:","documentation",["decoration","distraction","deletion"],"Records capture the product's design.")
H('411.d.8.B',4,"A bill of materials lists each part and its:","quantity",["rumor","nickname","favorite color"],"A BOM records what is in the assembly.")
H('411.d.8.C',3,"The part that transfers motor power to the wheels in a toy car is part of the:","drive system",["packaging","label","manual"],"Drive systems carry power.")
H('411.d.8.C',4,"Counting teeth on two meshing gears lets you compute the:","gear ratio",["price","weight of the box","color"],"Ratio = teeth driven / teeth driver.")
H('411.d.8.D',3,"A housing or cover on a product mainly serves to protect internal parts and provide:","a shape for the user",["extra weight only","noise","no function"],"Covers protect and shape the product.")
H('411.d.8.D',4,"Switches and buttons on a device are its:","controls",["housings","fasteners","gears"],"Controls let the user operate it.")
H('411.d.8.E',3,"A caliper is used to measure the:","dimensions of a part",["temperature","speed of sound","color"],"Calipers measure small lengths precisely.")
H('411.d.8.E',4,"Measuring a part three times and averaging helps reduce:","measurement error",["part weight","cost of tools","paint use"],"Repeated measurement improves accuracy.")
H('411.d.8.F',3,"Magnet tests, hardness tests, and visual inspection help identify a part's:","material",["owner","price tag","shipping address"],"Simple tests suggest the material.")
H('411.d.8.F',4,"A part that is attracted to a magnet is likely made of:","iron or steel",["aluminum","copper","plastic"],"Ferrous metals are magnetic.")
H('411.d.8.G',3,"Seams and ejector pin marks on a plastic part suggest it was made by:","injection molding",["hand carving","knitting","weaving"],"Molding leaves characteristic marks.")
H('411.d.8.G',4,"A part with a rough, grainy surface and a visible parting line was probably produced by:","casting",["printing","sewing","drawing"],"Casting leaves seams and texture.")
H('411.d.8.H',3,"Observing the order in which parts are removed helps you understand the product's:","assembly process",["resale price","advertising","shipping route"],"Reverse order reveals how it was assembled.")
H('411.d.8.H',4,"Screws, clips, and adhesives found during disassembly are called:","fasteners",["covers","gears","controls"],"Fasteners hold parts together.")
H('411.d.9.A',3,"Stamping makes a part by pressing sheet metal in a:","die",["bucket","blender","drawer"],"A die shapes the metal.")
H('411.d.9.A',4,"A car door panel is commonly formed from sheet steel by:","stamping",["casting","sintering","knitting"],"Large panels are stamped.")
H('411.d.9.B',3,"In injection molding, plastic pellets are loaded into a hopper and melted by a:","heater",["freezer","fan","magnet"],"The barrel heats the plastic.")
H('411.d.9.B',4,"After melted plastic is injected into a mold, the part must be allowed to:","cool and harden",["boil","evaporate","freeze the machine"],"Cooling sets the shape.")
H('411.d.9.C',3,"In casting, a furnace melts metal that is then poured into a:","mold",["bucket of paint","vending machine","sink"],"The mold gives the shape.")
H('411.d.9.C',4,"A cavity shaped like the desired part is used in:","casting and molding",["knitting","painting walls","drawing"],"Both use a shaped cavity.")
H('411.d.9.D',3,"Sintering forms solid parts by heating compacted metal powder below its:","melting point",["freezing point","boiling point of water","shadow"],"Particles bond without fully melting.")
H('411.d.9.D',4,"A porous metal bearing may be made by sintering because the process leaves tiny:","pores",["screws","colors","wires"],"Pores can hold lubricant.")
H('411.d.9.E',3,"Drilling, milling, and turning are examples of:","material removal",["casting","molding","stamping"],"They cut material away.")
H('411.d.9.E',4,"A lathe produces round parts by spinning the workpiece against a:","cutting tool",["magnet","mold","paintbrush"],"Turning removes material.")
H('411.d.9.F',3,"A jig or fixture holds a workpiece in place during:","manufacturing or assembly",["sleep","music","lunch"],"Fixtures keep parts positioned.")
H('411.d.9.F',4,"Using a fixture so every part is positioned the same way improves:","repeatability",["confusion","noise","rust"],"Consistent positions give consistent parts.")
H('411.d.9.G',3,"A material well suited to casting because it melts easily is:","aluminum",["glass fiber cloth","wood","rubber band"],"Aluminum casts well.")
H('411.d.9.G',4,"Sheet steel is a suitable material for stamping because it can be:","formed without cracking",["dissolved in water","blown like glass","burned"],"Ductile sheet forms well.")
H('411.d.9.H',3,"Choosing a manufacturing process depends on the part's shape, material, and the number to be:","produced",["admired","hidden","renamed"],"Quantity affects process choice.")
H('411.d.9.H',4,"Making millions of identical plastic parts at low cost per part usually favors:","injection molding",["hand carving","one-off machining","sculpting"],"Molds pay off at high volume.")
H('411.d.10.A',3,"Joining two metal parts by melting them together at the joint is called:","welding",["gluing","stapling","taping"],"Welding fuses the metals.")
H('411.d.10.A',4,"Joining two plastic or wood parts with a chemical that cures between them is:","adhesive bonding",["welding with an arc","casting","stamping"],"Adhesives bond surfaces.")
H('411.d.10.B',3,"A joining method that can be taken apart later without damage is a:","bolted joint",["welded joint","brazed joint","glued joint"],"Bolts can be removed.")
H('411.d.10.B',4,"An engineer choosing between welding and screws should weigh strength, cost, and whether the joint must be:","disassembled",["admired","painted blue","named"],"Serviceability matters.")
H('411.d.10.C',3,"Planning the order in which parts are put together is an:","assembly strategy",["advertising plan","lunch plan","music plan"],"Assembly order affects cost and quality.")
H('411.d.10.C',4,"Designing parts so they can only be installed one correct way helps prevent:","assembly errors",["good sales","strong parts","low cost"],"Error-proofing reduces mistakes.")
H('411.d.11.A',3,"FMEA stands for failure modes and effects:","analysis",["agreement","adjustment","assembly"],"It studies how things can fail.")
H('411.d.11.A',4,"In FMEA, a failure mode is a way in which a part could:","fail to work",["be painted","be sold","be named"],"Failure modes describe how failure happens.")
H('411.d.11.B',3,"Quality function deployment, or QFD, helps teams connect customer needs to:","engineering requirements",["lunch menus","dress codes","team songs"],"QFD translates voice of customer.")
H('411.d.11.B',4,"A house of quality is a chart used in:","QFD",["welding","stamping","sintering"],"QFD uses the house of quality matrix.")
H('411.d.11.C',3,"A list of measurable targets that a design must meet is an:","engineering requirements list",["advertisement","poem","guest list"],"Requirements make goals testable.")
H('411.d.11.C',4,"A requirement such as 'must support 20 kg' is useful because it is:","measurable",["vague","secret","funny"],"Measurable requirements can be tested.")
H('411.d.11.D',3,"After testing, an opportunity for improvement might be to reduce the product's:","weight or cost",["name","color words","fan club"],"Tests reveal what to improve.")
H('411.d.11.D',4,"If a prototype meets the strength target but is too heavy, the team should look for a way to make it:","lighter while staying strong",["weaker","more colorful","louder"],"Redesign to balance requirements.")
H('411.d.11.E',3,"A test that checks whether a design meets a requirement is a:","verification test",["rumor","guess","coin toss"],"Verification compares results to requirements.")
H('411.d.11.E',4,"To test if a latch survives repeated use, the team would run a:","cycle test",["paint test","taste test","speed reading test"],"Cycle tests repeat the motion.")
H('411.d.12.A',3,"The study of how energy moves from a warm object to a cooler one is:","heat transfer",["optics","genetics","statistics"],"Heat flows from hot to cold.")
H('411.d.12.A',4,"A heat sink on a computer chip works by increasing the surface area for:","cooling",["color","sound","weight"],"More area transfers heat away.")
H('411.d.12.B',3,"Thermodynamics studies how energy is converted between heat and:","work",["color","words","paint"],"Engines convert heat to work.")
H('411.d.12.B',4,"A car engine converts the energy of burning fuel into motion and waste:","heat",["paint","sound waves only","clouds"],"Not all energy becomes useful work.")
H('411.d.12.C',3,"Stress is force divided by:","area",["time","speed","color"],"Stress = F / A.")
H('411.d.12.C',4,"A 1,000 N load pulls on a rod with a cross-section of 0.5 square centimeters. The stress is:","2,000 N per square centimeter",["500 N per square centimeter","0.0005 N per square centimeter","1,000.5 N per square centimeter"],"1,000 / 0.5 = 2,000.")
H('411.d.12.D',3,"A material that returns to its original shape after a load is removed is behaving:","elastically",["permanently","randomly","invisibly"],"Elastic deformation is reversible.")
H('411.d.12.D',4,"Strain is the change in length divided by the:","original length",["new color","weight","price"],"Strain = delta L / L.")
H('411.d.12.E',3,"A shock absorber reduces bouncing by providing:","damping",["heating","lighting","cooling only"],"Dampers dissipate vibration energy.")
H('411.d.12.E',4,"A stiffer spring has a larger spring:","coefficient",["color","label","tag"],"A higher constant means more force per stretch.")
H('411.d.12.F',3,"An engineer choosing a lightweight, corrosion-resistant metal for a boat part might pick:","aluminum",["iron nail steel unprotected","raw chalk","wet paper"],"Aluminum resists corrosion and is light.")
H('411.d.12.F',4,"Compared with steel, a polymer part is usually lighter but:","less stiff",["much heavier","always stronger","magnetic"],"Plastics are typically less stiff.")
H('411.d.12.G',3,"Mass flow rate describes how much fluid mass passes a point each:","second",["meter","degree","newton"],"It is mass per unit time.")
H('411.d.12.G',4,"A fluid that resists flowing, such as honey, has a high:","viscosity",["compressibility","pressure","brightness"],"Viscosity measures resistance to flow.")
H('411.d.12.H',3,"A thermostat that turns a heater on and off based on room temperature is a:","closed-loop control",["open-loop timer only","broken system","static load"],"It uses feedback from a sensor.")
H('411.d.12.H',4,"A toaster that runs for a fixed time regardless of toast color is an:","open-loop control",["closed-loop control","feedback system","sensor system"],"It has no feedback.")
H('411.d.12.I',3,"Software that simulates stresses in a part before it is built is a:","computational tool",["paintbrush","wrench","level"],"Simulation tools predict performance.")
H('411.d.12.I',4,"Computer-aided design software lets engineers create and modify:","digital models of parts",["real metal","weather","recipes only"],"CAD builds digital models.")

H('410.d.5.A',3,"A quantity that has both size and direction, such as a push to the east, is called a:","vector",["scalar","constant","ratio"],"Vectors carry magnitude and direction.")
H('410.d.5.A',4,"A temperature of 20 degrees Celsius is a scalar because it has no:","direction",["number","unit","value"],"Scalars are described by magnitude alone.")
H('411.d.3.C',3,"On a project timeline, completing the first working prototype is best marked as a:","milestone",["mistake","lunch","footnote"],"Milestones mark important progress points.")
H('411.d.3.C',4,"A written report that a student team must submit at the end of the unit is one of the project's:","deliverables",["rumors","hobbies","spare parts"],"Deliverables are items handed over.")

